use vstd::prelude::*;

verus! {
    // The function copies a vector of Copy elements.
    // It returns a new vector with the same elements and length as the input.
    fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
        ensures
            result.len() == a.len(),
            forall|i: usize| (i < a.len()) ==> result[i] == a[i],
            // input vector not modified (immutable borrow in Rust ensures this)
    {
        let mut result = Vec::<T>::new();
        let mut idx: usize = 0;
        while idx < a.len()
            invariant
                idx <= a.len(),
                result.len() == idx,
                forall|j: usize| (j < idx) ==> result[j] == a[j],
            decreases a.len() - idx,
        {
            // Push the current element into result
            result.push(a[idx]);
            idx = idx + 1;
        }
        result
    }
}
